def smallest_possible_value(hex_diff):
    from itertools import permutations

    for d1, d2 in permutations(hex_diff, 2):
        if d1 != d2:
            break
    else:
        return 'NO'

    min_value = 0
    for i in range(len(hex_diff)):
        if hex_diff[i] == '0':
            continue
        tens = (ord(hex_diff[i]) - ord('0')) * 16
        min_value += tens * abs(i - d1)

