def calculate_wins(a, b, m, piles):
    w_a, w_b, w_f, w_s = 0, 0, 0, 0

    # Calculate the number of wins for each player
    for i, v in enumerate(piles, 1):
        c = gcd(a, b)
        if v % c == 0:
            wins = (v // c) * (max(a, b))
        else:
            wins = (v // c) * (max(a, b)) + 1
        if i % 2 == 1:
            wins += 1
        if i % 2 != 0:
            wins = wins * 2 - 1
        if i % 2 == 1:
            w_a += wins
        elif i % 2 == 0:
            w_b += wins

    # Calculate the number of wins for the second player
    for i, v in enumerate(piles, 1):
        if v % b == 0:
            wins = v // b
        elif v < a:
            wins = v % a + 1
        else:
            wins = a + 1
        w_s += wins

    return w_a, w_b, w_f, w_s

