from heapq import heapreplace, heappop, heapify
from itertools import accumulate

def find_max_sensors(n, y1, a, m, y2, b):
    # Initialize necessary data structures
    admissible = {}
    admissible[0] = 0
    max_peak = -1

    for i in a:
        if i < y1:
            continue
        if i not in admissible:
            admissible[i] = max_peak + 1
            max_peak = admissible[i]
        else:
            admissible[i] = max_peak + 1

    admissible_y1 = (i for i in accumulate(admissible.values()) if max_peak + 2 <= i)

    admissible = {}
    admissible[0] = 0
    max_peak = -1

    for i in b:
        if i < y2:
            continue
        if i not in admissible:
            admissible[i] = max_peak + 1
            max_peak = admissible[i]
        else:
            admissible[i] = max_peak + 1

    admissible_y2 = (i for i in accumulate(admissible.values()) if max_peak + 2 <= i)

    horizon = [(-e, i) for i, e in admissible_y1]
    horizon.extend([(-e, i) for i, e in admissible_y2])

    for _ in range(n):
        horizon.sort()
        if horizon[-1][1] // (-horizon[-1][0]):
            heappop(horizon)

