    def __init__(self, rows, cols, keys, exits):
        self.rows = rows
        self.cols = cols
        self.keys = set(keys)
        self.exits = set(exits)
        self.path = []

    def solve(self, start_row, start_col, keys, exits, max_keys):
        grid = copy.deepcopy(self.grid)
        for direction, (dr, dc) in DIRECTIONS.items():
            for i in range(max_keys):
                new_row, new_col = start_row + dr * i, start_col + dc * i
                if 0 <= new_row < self.rows and 0 <= new_col < self.cols:
                    if grid[new_row][new_col] == 1 and (new_row, new_col) not in exits and (new_row, new_col) in keys:
                        start_row, start_col = new_row, new_col
                        break
        if start_row < 0 or start_row >= self.rows or start_col < 0 or start_col >= self.cols:
            raise ValueError("Invalid starting cell")

        def dfs(row, col, current_keys):
            current_keys.add((row, col))
            if (row, col) in self.exits:
                self.path.append("terminate")
                return True
            for direction, (dr, dc) in DIRECTIONS.items():
                new_row, new_col = row + dr, col + dc
                if (new_row, new_col) not in current_keys:
                    did_open = False
                    if grid[new_row][new_col] == -1:
                        grid[new_row][new_col] = 0
                        did_open = True
                    if did_open and dfs(new_row, new_col, list(current_keys)):
                        return True
            if did_open:
