from collections import Counter, defaultdict

def build_tree(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    return graph

def shortest_path_tree(n, graph, root):
    depth = defaultdict(list)
    q = [root]
    depth[0] = [1]
    while q:
        parent = q.pop()
        for child in graph[parent]:
            if child not in depth:
                depth[len(depth)].append(child)
                q.append(child)
    return depth

def get_sequence(n, depths):
    sequence = []
    for i in range(len(depths)):
        for j in range(depths[i], -1, -1):
            while depth[i][j] > 0:
                sequence.append(i)
                depth[i][j] -= 1
    return sequence

def reduce_sequence(sequence, l):
    counter = Counter(sequence)
    valid_elements = [i for i, frequency in counter.items() if frequency >= l]
    reduced_sequence = sorted(valid_elements, key=lambda x: (counter[x], -sequence.count(x)), reverse=True)
    for i in range(len(sequence)):
        if sequence[i] != reduced_sequence[i]:
            return index
    return sequence.index(reduced_sequence[0]), sequence

def get_answer(index, n, depths, sequence, l, k):
    if len(sequence) < k:
        return -1
    sequence, index = reduce_sequence(sequence, l)
    return sequence[index]

