def XOR_queries(n, p, q):
    ice_cream = 1
    for i in range(1, min(p, 130) + 1):
        if (i & (i - 1)) == 0:
            ice_cream *= 2
    if n > p:
        p = n
    while p < (1 << q):
        p <<= 1
        if p - n >= p:
            if p - n == 1:
                return 2
            total_wines = 0
            for i in range(131):
                if (i & (i - 1)) == 0:
                    total_wines += 1

            pow_of_2 = 1
            for i in range(q):
                pow_of_2 *= 2
            return total_wines ^ pow_of_2
    return XOR_queries(n - p + 1)

