from collections import deque

def max_registrations(n, y1, sensors1, m, y2, sensors2):
    registers1 = set()
    registers2 = set()

    bfs_search1 = deque([(s, 1) for s in sensors1])
    while bfs_search1:
        i, c = bfs_search1.popleft()
        registers1.add((i, c))

        if i - 1 >= y1:
            if (i - 1, c + 1) not in registers1:
                bfs_search1.append((i - 1, c + 1))

        if i + 1 <= y1:
            if (i + 1, c + 1) not in registers1:
                bfs_search1.append((i + 1, c + 1))

        bfs_search2 = deque([(s, 1) for s in sensors2])
        while bfs_search2:
            i, c = bfs_search2.popleft()
            registers2.add((i, c))

            if i + 1 <= y2:
                if (i + 1, c + 1) not in registers2:
                    bfs_search2.append((i + 1, c + 1))

            if i - 1 >= y2:
                if (i - 1, c + 1) not in registers2:
                    bfs_search2.append((i - 1, c + 1))

    return max(len(registers1), len(registers2))

