def restore_array(n, m, copies):
    copies = [tuple(r) for r in copies]  # Store copies as tuples for O(n) checks
    for i in range(1, 3**m):
        block = i & (i - 1) ^ i  # Bits set bits(row bits)
        if not any(i & block for i in blocks):
            for k in range(m):
                if not any(block & blocks[k] for blocks in db):
                    restore = [[x & ~block for x in r] for r in copies]
                    if check(restore, db if n == 1 else copies if n == m else None):
                        return "Yes"
    return "No"

