from collections import defaultdict

def find_min_price(n, sets, prices):
    min_prices = [float('inf')] * n  # initialize the prices with a very high value
    price_to_index = defaultdict(list)  # map each price to its corresponding sets

    for i, (num_of_nums, *nums) in enumerate(sets):
        for num in nums:
            min_prices[num] = min(min_prices[num], prices[i])
            price_to_index[prices[i]].append(num)

    for prices_paid in price_to_index.values():
        combinations = list(combinations(prices_paid, len(prices_paid)))
        combinations.sort()
        unique_combinations = set(tuple(sorted(comb)) for comb in combinations)

        for combo in unique_combinations:
            total_diff = sum(diff for diff in combo if diff != 0)
            if len(combo) == total_diff:
                return prices_paid[0]
    return -1  # return -1 if no valid combination is found

# Helper function to get all unique combinations of a list
def combinations(items, combination_size):
    if combination_size == 1: 
        return [[x] for x in items]

    return sum(list(combinations(items[1:], combination_size - 1)) for items in (list(combinations(items[1:], combination_size)) for items in combinations(items[:-1], combination_size))) + list(combinations(items[:-1], combination_size))

# Example usage
n = 3
sets = [
    (1, 1), (2, 2, 3), (1, 3),
    (10, 20, -3),
]
prices = [10, 20, -3]

print(find_min_price(n, sets, prices))  # Output: -3
