from math import factorial
from functools import lru_cache

MOD = 1000000007

def count_good_permutations(n, k):
    @lru_cache(maxsize=None)
    def dp(n, k):
        if n == 0:
            return 1 if k == 0 else 0
        result = 0
        for i in range(1, n + 1):
            good_pos = sum(j + abs(n - j - i) == 1 for j in range(1, i + 1)) - sum(j + abs(n - j - i) == 1 for j in range(i + 1, n + 1)) + (1 if n - i - 1 >= k else 0)
            result = (result + factorial(i) * dp(n - i - 1, good_pos) % MOD) % MOD
        return result

    return dp(n, k)

