def bfs(graph, start, color):
    queue = [(start, 0)]
    colors = set()
    colors.add(start)
    while queue:
        node, color = queue.pop(0)
        if node not in colors:
            colors.add(node)
        for neighbor in graph[node]:
            if neighbor not in colors and bcolor[neighbor] != color:
                return False
            if neighbor not in colors and not dfs(graph, neighbor, bcolor[neighbor], visited, queue):
                return False
    return True

def dfs(graph, start, current_color, visited, queue):
    visited[start] = True
    queue.append(start)
    for neighbor in graph[start]:
        if neighbor not in visited and not dfs(graph, neighbor, current_color, visited, queue):
            queue.remove(start)
    queue.pop(0)
    return queue

